  {mapsTo : Set.MapsTo curve (Set.Icc 0 1) S}
  {semialgebraic : BfgsVerification.RealAlgebraicGeometry.IsSemialgebraicCurveOn curve (Set.Icc 0 1)}
  {curve_1 : ℝ → σ → ℝ} {continuousOn_1 : ContinuousOn curve_1 (Set.Icc 0 1)} {source_1 : curve_1 0 = x}
  {target_1 : curve_1 1 = y} {mapsTo_1 : Set.MapsTo curve_1 (Set.Icc 0 1) S}
  {semialgebraic_1 : BfgsVerification.RealAlgebraicGeometry.IsSemialgebraicCurveOn curve_1 (Set.Icc 0 1)},
  { curve := curve, continuousOn := continuousOn, source := source, target := target, mapsTo := mapsTo,
        semialgebraic := semialgebraic } =
      { curve := curve_1, continuousOn := continuousOn_1, source := source_1, target := target_1, mapsTo := mapsTo_1,
        semialgebraic := semialgebraic_1 } →
    curve = curve_1

∀ {E : Type u_1} {inst : NormedAddCommGroup E} {inst_1 : NormedSpace ℝ E} {S : Set E} {x y : E} {curve : ℝ → E}
  {continuousOn : ContinuousOn curve (Set.Icc 0 1)} {source : curve 0 = x} {target : curve 1 = y}
  {mapsTo : Set.MapsTo curve (Set.Icc 0 1) S} {exceptions : Finset ℝ}
  {smoothAt : ∀ t ∈ Set.Ioo 0 1, t ∉ exceptions → ContDiffAt ℝ (↑⊤) curve t} {curve_1 : ℝ → E}
  {continuousOn_1 : ContinuousOn curve_1 (Set.Icc 0 1)} {source_1 : curve_1 0 = x} {target_1 : curve_1 1 = y}
  {mapsTo_1 : Set.MapsTo curve_1 (Set.Icc 0 1) S} {exceptions_1 : Finset ℝ}
  {smoothAt_1 : ∀ t ∈ Set.Ioo 0 1, t ∉ exceptions_1 → ContDiffAt ℝ (↑⊤) curve_1 t},
  { curve := curve, continuousOn := continuousOn, source := source, target := target, mapsTo := mapsTo,
        exceptions := exceptions, smoothAt := smoothAt } =
      { curve := curve_1, continuousOn := continuousOn_1, source := source_1, target := target_1, mapsTo := mapsTo_1,
        exceptions := exceptions_1, smoothAt := smoothAt_1 } →
    curve = curve_1 ∧ exceptions = exceptions_1

∀ {σ : Type u_1} {inst : Fintype σ} {S : Set (σ → ℝ)} {x y : σ → ℝ}
  {path : BfgsVerification.RealAlgebraicGeometry.PiecewiseSmoothPath S x y}
  {semialgebraic : BfgsVerification.RealAlgebraicGeometry.IsSemialgebraicCurveOn path.curve (Set.Icc 0 1)}
  {path_1 : BfgsVerification.RealAlgebraicGeometry.PiecewiseSmoothPath S x y}
  {semialgebraic_1 : BfgsVerification.RealAlgebraicGeometry.IsSemialgebraicCurveOn path_1.curve (Set.Icc 0 1)},
  { path := path, semialgebraic := semialgebraic } = { path := path_1, semialgebraic := semialgebraic_1 } →
    path = path_1

∀ {x : BfgsVerification.Vec 2} {H : BfgsVerification.Mat 2} {g : BfgsVerification.Vec 2} {positive : Matrix.PosDef H}
  {derivative : HasFDerivAt BfgsVerification.TwoPieceBudget.objective (BfgsVerification.gradientFunctional g) x}
  {x_1 : BfgsVerification.Vec 2} {H_1 : BfgsVerification.Mat 2} {g_1 : BfgsVerification.Vec 2}
  {positive_1 : Matrix.PosDef H_1}
  {derivative_1 : HasFDerivAt BfgsVerification.TwoPieceBudget.objective (BfgsVerification.gradientFunctional g_1) x_1},
  { x := x, H := H, g := g, positive := positive, derivative := derivative } =
      { x := x_1, H := H_1, g := g_1, positive := positive_1, derivative := derivative_1 } →
    x = x_1 ∧ H = H_1 ∧ g = g_1

∀ {m : ℕ} {P : BfgsVerification.Parabolic.Family m} {count : ℕ} {count_pos : 0 < count} {index : Fin count → Fin m}
  {essential : ∀ (i : Fin count), P.Essential (index i)} {covers : ∀ (i : Fin m), P.Essential i → ∃ k, index k = i}
  {slopes_strictMono : StrictMono fun i => P.b (index i)} {count_1 : ℕ} {count_pos_1 : 0 < count_1}
  {index_1 : Fin count_1 → Fin m} {essential_1 : ∀ (i : Fin count_1), P.Essential (index_1 i)}
  {covers_1 : ∀ (i : Fin m), P.Essential i → ∃ k, index_1 k = i}
  {slopes_strictMono_1 : StrictMono fun i => P.b (index_1 i)},
  { count := count, count_pos := count_pos, index := index, essential := essential, covers := covers,
        slopes_strictMono := slopes_strictMono } =
      { count := count_1, count_pos := count_pos_1, index := index_1, essential := essential_1, covers := covers_1,
        slopes_strictMono := slopes_strictMono_1 } →
    count = count_1 ∧ HEq index index_1
